const PR16=[{label:"Ví dụ: Sắp xếp chọn",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {29, 10, 14, 37, 13, 5, 22};\n    int n = a.size();\n    for (int i = 0; i < n - 1; i++) {\n        int m = i;\n        for (int j = i + 1; j < n; j++) {\n            if (a[j] < a[m]) m = j;\n        }\n        swap(a[i], a[m]);\n    }\n    for (int x : a) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i","j","m"],range:["i","n-1"]}],py:{code:"a = [29, 10, 14, 37, 13, 5, 22]\nn = len(a)\nfor i in range(n - 1):\n    m = i\n    for j in range(i + 1, n):\n        if a[j] < a[m]:\n            m = j\n    a[i], a[m] = a[m], a[i]\nprint(*a)",note:"m trỏ vào số nhỏ nhất tìm được tới giờ trong đoạn a[i..]. Cuối lượt, a[i], a[m] = a[m], a[i] đổi chỗ hai phần tử trong một dòng."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 29, 10, 14, 37, 13, 5, 22 };\n        int n = a.Length;\n        for (int i = 0; i < n - 1; i++)\n        {\n            int m = i;\n            for (int j = i + 1; j < n; j++)\n            {\n                if (a[j] < a[m]) m = j;\n            }\n            (a[i], a[m]) = (a[m], a[i]);\n        }\n        Console.WriteLine(string.Join(\" \", a));\n    }\n}",note:"(a[i], a[m]) = (a[m], a[i]); là cách đổi chỗ hai phần tử ngắn gọn của C# (gán theo bộ giá trị, có từ C# 7): cả hai giá trị vế phải được lấy ra trước rồi mới ghi."}},{label:"Ví dụ: Sắp xếp chèn",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {29, 10, 14, 37, 13, 5, 22};\n    int n = a.size();\n    for (int i = 1; i < n; i++) {\n        int x = a[i];\n        int j = i - 1;\n        while (j >= 0 && a[j] > x) {\n            a[j + 1] = a[j];\n            j--;\n        }\n        a[j + 1] = x;\n    }\n    for (int v : a) cout << v << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i","j"],range:["0","i"]},{type:"vars",names:["x"]}],py:{code:"a = [29, 10, 14, 37, 13, 5, 22]\nn = len(a)\nfor i in range(1, n):\n    x = a[i]\n    j = i - 1\n    while j >= 0 and a[j] > x:\n        a[j + 1] = a[j]\n        j -= 1\n    a[j + 1] = x\nprint(*a)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 29, 10, 14, 37, 13, 5, 22 };\n        int n = a.Length;\n        for (int i = 1; i < n; i++)\n        {\n            int x = a[i];\n            int j = i - 1;\n            while (j >= 0 && a[j] > x)\n            {\n                a[j + 1] = a[j];\n                j--;\n            }\n            a[j + 1] = x;\n        }\n        Console.WriteLine(string.Join(\" \", a));\n    }\n}"}},{label:"Ví dụ: Sắp xếp nổi bọt có dừng sớm",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {29, 10, 14, 37, 13, 5, 22};\n    int n = a.size(), doi = 0;\n    for (int i = 0; i < n - 1; i++) {\n        bool coDoi = false;\n        for (int j = 0; j + 1 < n - i; j++) {\n            if (a[j] > a[j + 1]) {\n                swap(a[j], a[j + 1]);\n                doi++;\n                coDoi = true;\n            }\n        }\n        if (!coDoi) break;\n    }\n    for (int x : a) cout << x << \" \";\n    cout << \"\\n\" << doi << \" lan doi cho\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["j"],sorted:{from:"n-i"}},{type:"vars",names:["doi"]}],predict:[{line:12,kind:"swap",q:"Hai cột nào sắp đổi chỗ? (bấm 2 cột)"}],py:{code:"a = [29, 10, 14, 37, 13, 5, 22]\nn = len(a)\ndoi = 0\nfor i in range(n - 1):\n    coDoi = False\n    for j in range(n - 1 - i):\n        if a[j] > a[j + 1]:\n            a[j], a[j + 1] = a[j + 1], a[j]\n            doi += 1\n            coDoi = True\n    if not coDoi:\n        break\nprint(*a)\nprint(doi, \"lan doi cho\")",predict:[{line:8,kind:"swap",q:"Hai cột nào sắp đổi chỗ? (bấm 2 cột)"}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 29, 10, 14, 37, 13, 5, 22 };\n        int n = a.Length, doi = 0;\n        for (int i = 0; i < n - 1; i++)\n        {\n            bool coDoi = false;\n            for (int j = 0; j + 1 < n - i; j++)\n            {\n                if (a[j] > a[j + 1])\n                {\n                    (a[j], a[j + 1]) = (a[j + 1], a[j]);\n                    doi++;\n                    coDoi = true;\n                }\n            }\n            if (!coDoi) break;\n        }\n        Console.WriteLine(string.Join(\" \", a));\n        Console.WriteLine(doi + \" lan doi cho\");\n    }\n}",predict:[{line:16,kind:"swap",q:"Hai cột nào sắp đổi chỗ? (bấm 2 cột)"}]}}];
