makeEx2(document.getElementById("ex-l16"),sim16,[{t:"Từng lượt của sắp xếp chèn",d:"Đầu vào: n (2 ≤ n ≤ 100) rồi n số nguyên. Đầu ra: n − 1 dòng; dòng thứ i (i = 1..n−1) là dãy sau khi chèn xong phần tử thứ i (chỉ số từ 0) bằng sắp xếp chèn, các số cách nhau một khoảng trắng.",tests:[{in:"4\n4 3 1 2",out:"3 4 1 2\n1 3 4 2\n1 2 3 4"},{in:"2\n1 2",out:"1 2"},{in:"3\n5 5 1",out:"5 5 1\n1 5 5"}],start:"#include <iostream>\nusing namespace std;\n\nint a[100];\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    // sau mỗi lượt chèn, in cả dãy\n    return 0;\n}",py:{start:"n = int(input())\na = list(map(int, input().split()))\n# sau mỗi lượt chèn, in cả dãy",hints:["Lượt i: cầm x = a[i], dời các số lớn hơn x (không phải lớn hơn hoặc bằng) sang phải, đặt x vào a[j + 1].","In cả dãy sau mỗi lượt bằng print(*a), kể cả khi dãy không đổi."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // sau mỗi lượt chèn, in cả dãy\n    }\n}",hints:["Lượt i: cầm x = a[i], dịch các số lớn hơn x (không phải lớn hơn hoặc bằng) sang phải, đặt x vào a[j + 1].","In cả dãy sau mỗi lượt, kể cả khi dãy không đổi: string.Join(\" \", a)."]}},{t:"Đếm nghịch thế",d:"Đầu vào: n (1 ≤ n ≤ 300) rồi n số nguyên. Đầu ra: số lần đổi chỗ mà sắp xếp nổi bọt thực hiện để xếp dãy tăng dần (bằng số cặp i < j có aᵢ > aⱼ).",tests:[{in:"7\n29 10 14 37 13 5 22",out:"12"},{in:"3\n1 2 3",out:"0"},{in:"4\n4 3 2 1",out:"6"},{in:"5\n2 2 1 1 3",out:"4"}],start:"#include <iostream>\nusing namespace std;\n\nint a[300];\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    return 0;\n}",py:{start:"n = int(input())\na = list(map(int, input().split()))",hints:["Cài nổi bọt và đếm số lần đổi chỗ; hoặc đếm trực tiếp các cặp i < j có a[i] > a[j].","Hai số bằng nhau không đổi chỗ (dùng >, không dùng >=)."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // đếm số lần đổi chỗ của sắp xếp nổi bọt\n    }\n}",hints:["Cài nổi bọt và đếm số lần đổi chỗ; hoặc đếm trực tiếp các cặp i < j có a[i] > a[j].","Hai số bằng nhau không đổi chỗ (dùng >, không dùng >=)."]}},{t:"Sắp xếp chọn: số lần đổi chỗ thật",d:"Đầu vào: n (1 ≤ n ≤ 300) rồi n số nguyên. Chạy sắp xếp chọn (lượt i tìm vị trí m của số nhỏ nhất trong a[i..n−1]; nếu có nhiều số nhỏ nhất, lấy vị trí đầu tiên; đổi a[i] với a[m] chỉ khi m ≠ i). Đầu ra: dòng một là dãy sau khi xếp, dòng hai là số lần đổi chỗ thực sự.",tests:[{in:"7\n29 10 14 37 13 5 22",out:"5 10 13 14 22 29 37\n4"},{in:"3\n1 2 3",out:"1 2 3\n0"},{in:"4\n4 3 2 1",out:"1 2 3 4\n2"},{in:"4\n2 1 2 1",out:"1 1 2 2\n2"}],start:"#include <iostream>\nusing namespace std;\n\nint a[300];\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    return 0;\n}",py:{start:"n = int(input())\na = list(map(int, input().split()))",hints:["“Vị trí đầu tiên của số nhỏ nhất”: chỉ đổi m khi a[j] nhỏ hơn hẳn a[m].","Chỉ đếm khi m ≠ i. Sắp xếp chọn đổi chỗ không quá n − 1 lần."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // sắp xếp chọn, chỉ đổi chỗ khi m != i\n    }\n}",hints:["“Vị trí đầu tiên của số nhỏ nhất”: chỉ đổi m khi a[j] nhỏ hơn hẳn a[m].","Chỉ đếm khi m ≠ i. Sắp xếp chọn đổi chỗ không quá n − 1 lần."]}}]);

makeQuiz("quiz16","score16",[{"q": "Sau lượt thứ i của sắp xếp chọn (tính từ 0), điều gì chắc chắn đúng?", "o": ["a[0..i] đã tăng nhưng có thể chưa phải các số nhỏ nhất", "a[0..i] là i + 1 số nhỏ nhất, đã tăng", "a[i..n−1] đã tăng", "Cả mảng đã tăng"], "a": 1, "e": "Mỗi lượt đưa số nhỏ nhất còn lại về đúng vị trí cuối cùng của nó."}, {"q": "Thuật toán nào chạy O(n) trên dãy đã sắp xếp sẵn?", "o": ["Sắp xếp chọn", "Sắp xếp chèn", "Cả hai", "Không thuật toán nào"], "a": 1, "e": "Mỗi lá bài chỉ so một lần với lá ngay trước, vòng while không chạy."}, {"q": "Dãy 3 1 2 có bao nhiêu nghịch thế?", "o": ["1", "2", "3", "0"], "a": 1, "e": "Các cặp (3,1) và (3,2)."}, {"q": "Sắp xếp nổi bọt sau lượt thứ nhất đảm bảo điều gì?", "o": ["Số nhỏ nhất ở đầu", "Số lớn nhất ở cuối", "Dãy đã tăng", "Nửa đầu đã tăng"], "a": 1, "e": "Số lớn nhất bị đẩy dần về cuối qua mỗi lần so sánh kề nhau."}, {"q": "n = 10⁵. Các thuật toán sắp xếp O(n²) cần khoảng bao nhiêu phép so sánh?", "o": ["10⁵", "1,7·10⁶", "5·10⁹", "10¹⁵"], "a": 2, "e": "n²/2 = 5·10⁹: quá chậm cho giới hạn 1 giây. Cần thuật toán O(n log n) ở hai bài sau."}]);

